on conflict do nothing;
update public.matches m set finalized_at = m.scheduled_at + make_interval(mins => m.duration_minutes) from public.competitions c where c.id = m.competition_id and c.event_id = 'af4e469b-d45f-5a9a-88e4-43a7af2ae72e' and m.queue_state = 'final';
update public.audit_log set at = (date '2026-05-31' + time '21:00') at time zone 'America/Vancouver' where event_id = 'af4e469b-d45f-5a9a-88e4-43a7af2ae72e';
